# -*- coding: utf-8 -*-
from lesson_authoring import entry as E
from author_batch200_root_liter_a import L,ARY,ATE,ACY,H
WD=[
E('nonliterary','英 /nɒnˈlɪtərəri/；美 /nɑːnˈlɪtəˌreri/','非文学的；不带文学风格的','文字主要是为了办事、说明或记录，而不是作为文学作品来欣赏。','non-“非” + literary。',H(ARY,'英语 non- + literary → nonliterary','文学的 → 非文学的、非文学风格的'),'说明书、会议记录和许多表格属于 nonliterary texts。这个分类通常只是在说用途或风格，不是在说它们写得差。反过来，文学作品也可能借用通知、账单这样的形式来创作。','nonliterary texts；nonliterary language；a nonliterary source。','nonliterary 说与文学的关系；illiterate 说读写能力或文字水平，两者不能互换。',('The exam includes both literary and nonliterary texts.','考试既包括文学文本，也包括非文学文本。'),('She used letters and other nonliterary sources to reconstruct daily life.','她利用书信等非文学资料还原当时的日常生活。'),sources=['https://en.wiktionary.org/wiki/nonliterary']),
E('biliterate','/baɪˈlɪtərət/','能用两种语言读写的','不只是两种语言都能聊，还能把两边的文字读进去、写出来。','bi-“二” + literate，仿照 bilingual 这一类构词方式。',H(ATE,'英语 bi- + literate → biliterate','有读写能力的 → 能用两种语言读写的'),'说一个人 biliterate in English and Spanish，重点落在两种语言的阅读和书写。口语很流利，不一定就能熟练阅读相应文字；反过来，两种读写能力也可能发展得不一样。','biliterate in two languages；become biliterate。','bilingual 通常更广泛地说两种语言的使用能力；biliterate 特别强调文字读写。biliteral 则与两个字母或两套文字有关。',('She is biliterate in English and Spanish.','她能用英语和西班牙语读写。'),('The school helps children become biliterate while maintaining their home language.','学校帮助孩子在保留家庭语言的同时，获得两种语言的读写能力。'),sources=['https://www.collinsdictionary.com/dictionary/english/biliterate','https://en.wiktionary.org/wiki/biliterate']),
E('biliteracy','/baɪˈlɪtərəsi/','双语读写能力','一个人能在两套语言文字之间来回阅读、书写，而不只是在口头上切换。','bi-“二” + literacy；与形容词 biliterate 相对应。',H(ACY,'英语 bi- + literacy → biliteracy','读写能力 → 两种语言或文字系统的读写能力'),'biliteracy 教育关心孩子怎样读懂并写出两种语言的文本，不是让他们机械抄两种字母。不同语言可能使用同一种字母表，也可能使用不同文字；两边的能力可以互相帮助，也各有需要练习的地方。','develop biliteracy；biliteracy education；support biliteracy。','biliteracy 强调两种读写能力；bilingualism 讨论双语使用的范围更广。两种语言的熟练程度不必完全相等才值得讨论双语读写。',('Reading stories in both languages helped develop her biliteracy.','用两种语言读故事，帮助她发展了双语读写能力。'),('The project supports biliteracy through family reading activities.','这个项目通过家庭阅读活动支持双语读写能力的发展。'),sources=['https://en.wiktionary.org/wiki/biliteracy','https://www.teachingenglish.org.uk/sites/teacheng/files/pub_F240%20Early%20Childhood%20Education%20inners%20FINAL%20web.pdf']),
E('multiliteracy','构词读法 /ˌmʌltiˈlɪtərəsi/','多元素养；理解和运用多种表达形式的能力','文字、图表、影像和声音放到眼前，能看懂它们如何传达意思，也会选择合适方式表达。','multi-“多种” + literacy；把读写能力的讨论扩展到多种媒介、表达方式与文化语境。',H(ACY,'英语 multi- + literacy → multiliteracy','读写素养 → 多种交流方式中的理解与表达能力'),'multiliteracy 常见于教育讨论。读一张地图、判断视频怎样剪辑、把调查结果做成图表，都可能进入这种学习框架。重点不是设备用得越多越好，而是能理解不同形式怎样组织信息，并作出判断。','develop multiliteracy；multiliteracy skills；multiliteracy education。','multiliteracy 突出多种表达与理解能力；biliteracy 专指两种语言或文字的读写。不同研究对术语边界会有不同界定。',('The lesson develops multiliteracy by combining maps, interviews, and written reports.','这节课结合地图、访谈和书面报告，培养多元素养。'),('Multiliteracy includes judging how images and words work together.','多元素养包括判断图像与文字怎样共同传达意思。'),sources=['https://www.oph.fi/sites/default/files/documents/curriculum_guidelines_for_literacy_training_in_liberal_adult_education_2017_0.pdf']),
E('transliteracy','构词读法 /trænzˈlɪtərəsi/','跨媒介读写与交流能力','同一件事，既能听人讲，也能读资料、看视频，再换一种媒介清楚地表达出来。','现代外形可看作 trans-“跨越” + literacy；提出这一研究概念的作者也说明它借用了 transliterate“转换文字系统”的想法，再扩展到不同交流媒介。',L+[['英语 transliterate／literacy','转换书写系统／读写能力'],['现代研究术语 transliteracy','跨平台、工具与媒介进行理解、表达和互动的能力']],'这里的跨越不限于屏幕：口述、手写、印刷、广播和网络交流都可以进入讨论。把一次采访做成文字摘要，再用图像和声音向不同受众讲清楚，是容易理解的例子。它不是 transliteration 的另一种拼写。','transliteracy skills；a transliteracy project；research on transliteracy。','transliteration 是把文字转写到另一套文字系统；transliteracy 研究跨媒介的理解和交流能力。两者命名有关，现代所指却不同。',('The project develops transliteracy through interviews, print sources, and digital storytelling.','这个项目通过访谈、印刷资料和数字叙事，培养跨媒介理解与表达能力。'),('The course treats transliteracy as more than the ability to use a new device.','这门课认为跨媒介素养不只是会用一个新设备。'),sources=['https://firstmonday.org/ojs/index.php/fm/article/download/2060/1908','https://en.wiktionary.org/wiki/transliteracy']),
E('literation','/ˌlɪtəˈreɪʃən/','用字母记录声音或词语〔少见〕','把耳朵听见的语言，换成纸面上可以看见的字母。','以拉丁 littera“字母”为材料，加英语 -ation 形成名词。',L+[['英语构词 littera + -ation → literation','字母 → 用字母表示语言声音或词语的过程']],'literation 是较少见的文字学用语，重点在“用字母表示”。它本身不保证一个字母只对应一个音，也不必然涉及从一套文字换到另一套文字。阅读旧式语言研究时，按这个基本动作理解即可。','a system of literation；literation of sounds。','literation 说用字母记录；transliteration 说转换到另一套书写系统；alliteration 则是头韵，三个词所做的事不同。',('The scholar proposed a system of literation for the recorded sounds.','学者提出了一套用字母记录这些声音的方法。'),('The chapter explains how literation makes spoken forms visible on the page.','这一章说明如何通过字母记录，把口语形式呈现在纸上。'),sources=['https://www.merriam-webster.com/dictionary/literation','https://en.wiktionary.org/wiki/literation']),
E('triliteral','/traɪˈlɪtərəl/','由三个字母组成的；三辅音词根的','把词的骨架抽出来，看到三个核心字母或辅音位置。','tri-“三” + 拉丁 littera“字母”这一构词材料 + -al。',L+[['英语 tri- + liter- + -al → triliteral','字母 → 三个字母的，尤其三个辅音的']],'普通字面义是由三个字母组成。闪米特语言的语法书里，triliteral root 常指由三个辅音构成的词根；例如讨论阿拉伯语 k-t-b 这一书写相关词根时会用到它。词根有三个辅音，不等于每个实际单词只能有三个字母。','a triliteral root；triliteral consonantal roots。','triliteral 看字母或词根辅音的数量；trisyllabic 看音节数，两者不是同一种计数。',('The lesson introduces several triliteral roots.','这节课介绍了几个三辅音词根。'),('A word formed from a triliteral root can contain more than three letters.','由三辅音词根构成的实际单词，可以不止三个字母。'),sources=['https://www.merriam-webster.com/dictionary/triliteral','https://en.wiktionary.org/wiki/triliteral']),
E('biliteral','/baɪˈlɪtərəl/','两个字母或辅音的；使用两种文字系统的','看结构时数到两个字母位置；看文本时，也可能是在说使用两套字母系统。','bi-“二” + literal 的“字母的”这一构词义。',L+[['英语 bi- + literal → biliteral','字母的 → 两个字母或两种字母系统的']],'语言学里的 biliteral root 是两个核心辅音的词根。biliteral inscription 也可说同一铭文用了两种字母系统。密码学还可借两类字形组合编码。每种用法都要认清“二”数的是什么。','a biliteral root；a biliteral inscription；a biliteral cipher。','biliteral 关注字母数量或文字形式；biliterate 关注人能否用两种语言读写。',('The grammar compares biliteral and triliteral roots.','这本文法书比较了双辅音词根与三辅音词根。'),('The catalogue describes the inscription as biliteral because it uses two scripts.','目录称这段铭文使用了两种文字系统，因此将它描述为 biliteral。'),sources=['https://www.merriam-webster.com/dictionary/biliteral','https://en.wiktionary.org/wiki/biliteral']),
E('quadriliteral','英 /ˌkwɒdrɪˈlɪtərəl/；美 /ˌkwɑːdrəˈlɪtərəl/','四个字母的；四辅音词根的','词根骨架里有四个辅音位置，而不是常见讨论中的三个。','quadri-“四” + literal 的字母义；现代英语的学术构词。',L+[['英语 quadri- + literal → quadriliteral','字母的 → 四个字母、尤其四个词根辅音的']],'在闪米特语言研究里，quadriliteral root 与 triliteral root 相对。它数的是词根中的核心辅音，不是断言单词只有四个音节，也不保证加上词形变化后仍只写四个字母。','a quadriliteral root；quadriliteral verbs。','quadriliteral 看四个字母或辅音位置；四音节要用 quadrisyllabic 或说 four syllables，不能混数。',('The chapter lists several quadriliteral roots beside the triliteral ones.','这一章在三辅音词根旁边列出了一些四辅音词根。'),('The teacher marked the four consonants of the quadriliteral root.','老师标出了这个四辅音词根中的四个辅音。'),sources=['https://www.merriam-webster.com/dictionary/quadriliteral','https://en.wiktionary.org/wiki/quadriliteral']),
E('uniliteral','/ˌjuːnɪˈlɪtərəl/','单字母的；只涉及一个字母的〔专业、少见〕','把表示单位缩到一个字母，一个位置就承担这里要表达的内容。','uni-“一” + literal 的字母义。',L+[['英语 uni- + literal → uniliteral','字母的 → 一个字母的']],'uniliteral abbreviation 是单字母缩写；某些文字研究里也用这个词描述对应单个辅音的符号。它说的是符号单位的数量或功能，不等于这个符号只可能有一种意义。','a uniliteral abbreviation；a uniliteral sign。','uniliteral 是一个字母的；unilateral 是单方面的，后者接“侧面”词根，不是字母词族。',('The table uses uniliteral abbreviations for the categories.','表格用单字母缩写表示各个类别。'),('The guide explains the value of each uniliteral sign.','指南解释了每个单辅音符号所表示的音值。'),sources=['https://www.merriam-webster.com/dictionary/uniliteral','https://en.wiktionary.org/wiki/uniliteral']),
E('multiliteral','构词读法 /ˌmʌltiˈlɪtərəl/','涉及多个字母的〔专业、少见〕','一个表示单位里用了不止一个字母，而不是用单独一个字母完成。','multi-“多个” + literal 的字母义。',L+[['英语 multi- + literal → multiliteral','字母的 → 涉及多个字母的']],'multiliteral 是宽泛的结构说明：用到多个字母。具体有几个、这些字母表示一个音还是别的单位，要由研究文本说明。它不是“多种文学”，也不能仅凭词形就把它等同于会多种语言。','a multiliteral symbol；a multiliteral representation。','multiliteral 说书写单位；multiliteracy 说多种理解和表达能力。多出来的词尾反映不同概念。',('The proposed system allows both single letters and multiliteral symbols.','这套拟议系统既允许使用单个字母，也允许使用多字母符号。'),('The article explains how to read each multiliteral representation.','文章解释了每一种多字母表示方式应该如何读取。'),sources=['https://en.wiktionary.org/wiki/multiliteral']),
]
